        var life = deadline(i) - (1 + a);
        if (life > 0) lasting += Math.min(1, life / 35);
      }
      if (a >= 0 && b >= 0) shared = true;
      if (a >= 0 && (b < 0 || a + 1 < b)) mineSpace++;
      else if (b >= 0 && (a < 0 || b < a + 1)) theirSpace++;
      else if (a >= 0 && b >= 0) {
        mineSpace += 0.5;
        theirSpace += 0.5;
      }
    }

    var exits = 0, bestContinuation = 0;
    for (var k = 0; k < 4; k++) {
      var nx = x + dx[k], ny = y + dy[k];
      if (!usable(nx, ny, 2)) continue;
      var q = ny * w + nx;
      exits++;
      var nextDist = distances(q, p, 2);
      var count = 0;
      for (i = 0; i < n; i++) {
        if (nextDist[i] >= 0) count++;
      }
      if (count > bestContinuation) bestContinuation = count;
    }

    var parityLimit = 2 * Math.min(black, white) +
      (black !== white ? 1 : 0);
    var score = 0.45 * reachable + 0.35 * parityLimit +
      0.35 * lasting + 0.35 * bestContinuation;

    if (shared) score += 0.8 * mineSpace - 0.65 * theirSpace;
    if (exits === 0) score -= 10000;
    else if (exits === 1) score -= 8;
    if (danger[p]) score -= 600;

    var remaining = deadline(p);
    if (remaining <= 2) score -= 80;
    else if (remaining <= 5) score -= 12;
    if (names[d] === you.dir) score += 0.05;

    if (score > bestScore) {
      bestScore = score;
      bestDir = names[d];
    }
  }

  return { dir: bestDir, boost: false };
}
